// Embeds templates/*.yml into the package as strings, so the browser build
// (the dashboard's setup screen) carries them without a file system.
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const read = (name) => readFileSync(resolve(root, 'templates', name), 'utf-8')

const target = resolve(root, 'src/generated/templates.ts')
const content = [
  '// Generated by scripts/embed-templates.mjs from templates/*.yml — do not edit.',
  `export const STORE_DEFAULTS = ${JSON.stringify(read('store-defaults.yml'))}`,
  `export const COUNTRY_TEMPLATE = ${JSON.stringify(read('country.yml'))}`,
  '',
].join('\n')
mkdirSync(dirname(target), { recursive: true })
writeFileSync(target, content)

// Sample data: its store files, and the CSVs the imports read. The CSVs are
// the server's own example files, so there is one copy of each.
const csv = (name) =>
  readFileSync(resolve(root, '../../spree/core/db/sample_data', `${name}.csv`), 'utf-8')
const sample = [
  '// Generated by scripts/embed-templates.mjs — do not edit.',
  ...['setup', 'catalog', 'wholesale'].map(
    (name) =>
      `export const ${name.toUpperCase()}_FILE = ${JSON.stringify(read(`sample-data/${name}.yml`))}`,
  ),
  ...['products', 'product_translations', 'customers', 'price_list_prices'].map(
    (name) => `export const ${name.toUpperCase()}_CSV = ${JSON.stringify(csv(name))}`,
  ),
  '',
].join('\n')
writeFileSync(resolve(root, 'src/generated/sample-data.ts'), sample)
